import type { Confidence, Verdict } from '../types'
import { verdictOf } from './verdicts'
import { DECLARATION, among, caseNames, caseStarts, fits, isTemplate, langOf } from './discovery'

// what the grader reads, and what its reply holds: pure text work, no engine calls

export const MAX_SOURCE = 40_000
// of a file too long to send whole: at most this much of its head (imports, helpers), and of
// any one case under review
export const MAX_HEAD = 12_000
export const MAX_BODY = 20_000

export const clamp = (s: string, n: number): string => (s.length > n ? `${s.slice(0, n - 1)}…` : s)
// What the grader reads: the whole file when it fits. Else, in file order: its head, the
// cases under review whole, each from its start to the next case's, and of what sits between
// the other cases, each piece that declares a name the shown code uses
export const excerptOf = (source: string, names: string[], file: string): string => {
  if (source.length <= MAX_SOURCE) return source
  const starts = caseStarts(source, file)
  const head = clamp(source.slice(0, starts[0]?.at ?? source.length), MAX_HEAD)
  const pieces = starts.map((start, i) => ({
    // a looped case is asked about by its expanded name: the loop that generates it is shown
    isChosen: names.some(name => fits(start.name, name)),
    whole: source.slice(start.at, starts[i + 1]?.at ?? source.length).trimEnd(),
    // what sits above the case's own line: comments, data, helpers
    declares: [...source.slice(start.at, start.opens).matchAll(DECLARATION)].map(m => (m[1] ?? m[2])!),
    gap: source.slice(start.at, start.opens).trimEnd(),
  }))
  const extra = new Set<number>()
  let shown = pieces.filter(p => p.isChosen).map(p => p.whole).join('\n')
  // a helper the shown code uses can use another, so until nothing more is named
  for (let isGrowing = true; isGrowing; ) {
    isGrowing = false
    pieces.forEach((p, i) => {
      if (p.isChosen || extra.has(i) || !p.declares.some(name => new RegExp(`\\b${name}\\b`).test(shown))) return
      extra.add(i)
      shown += `\n${p.gap}`
      isGrowing = true
    })
  }
  const note = langOf(file) === 'py' ? '#' : '//'
  const LEFT_OUT = `${note} … other tests left out …`
  const out = [head.trimEnd()]
  pieces.forEach((p, i) => {
    const piece = p.isChosen
      ? p.whole.length > MAX_BODY
        ? `${p.whole.slice(0, MAX_BODY)}\n${note} … the rest of this test is left out: it is too long to send …`
        : p.whole
      : extra.has(i)
        ? p.gap
        : null
    if (piece !== null) out.push(piece)
    else if (out[out.length - 1] !== LEFT_OUT) out.push(LEFT_OUT)
  })
  return out.join('\n\n')
}

// Of a file sent as an excerpt, the tests it leaves out, by name: the grader reads what the
// siblings cover (TestX_ThresholdBoundary) before it calls a case missing
const MAX_OTHERS = 80
export const othersOf = (source: string, names: string[], file: string): string[] => {
  const others = [...new Set(caseNames(source, file))].filter(n => !names.some(name => fits(n, name)))
  if (others.length === 0) return []
  const shown = others.slice(0, MAX_OTHERS).map(n => JSON.stringify(n)).join(', ')
  return [`The tests left out, by name: ${shown}${others.length > MAX_OTHERS ? ` and ${others.length - MAX_OTHERS} more` : ''}. A case one of them covers by its name is not missing.`]
}

// a case's own text, from its start to the next case's (a looped case's: its loop's); null
// when the file no longer has it
export const caseTextOf = (source: string, name: string, file: string): string | null => caseTextsOf(source, file)(name)
// the same for many names of one file, its cases found once
export const caseTextsOf = (source: string, file: string): ((name: string) => string | null) => {
  const starts = caseStarts(source, file)
  return name => {
    const i = starts.findIndex(s => fits(s.name, name))
    return i < 0 ? null : source.slice(starts[i]!.at, starts[i + 1]?.at ?? source.length).trimEnd()
  }
}

// The asked names that are cases a loop generates, each set under the loop's own name in the
// file: the grader is told so, to judge each by that loop's body with its variable bound
export const loopsOf = (source: string, names: string[], file: string): string[] => {
  const templates = [...new Set(caseNames(source, file))].filter(isTemplate)
  const byLoop = new Map<string, string[]>()
  for (const name of names) {
    const loop = isTemplate(name) ? undefined : templates.find(t => fits(t, name))
    if (loop) byLoop.set(loop, [...(byLoop.get(loop) ?? []), name])
  }
  return [...byLoop].map(([loop, cases]) => `${cases.map(c => JSON.stringify(c)).join(', ')} ${cases.length === 1 ? 'is a case' : 'are cases'} of the loop that declares the test ${JSON.stringify(loop)}: judge ${cases.length === 1 ? 'it' : 'each'} by that loop's body, its variable bound to the case's value.`)
}

// the verdicts in a grader reply; of one cut off before its closing ], each object that
// arrived whole (isCut)
const CONFIDENCES: readonly unknown[] = ['high', 'medium', 'low']
export const parseVerdicts = (text: string): { verdicts: Graded[]; isCut: boolean } => {
  const start = text.indexOf('[')
  if (start < 0) return { verdicts: [], isCut: false }
  const objects: unknown[] = []
  let depth = 0
  let from = -1
  let inString = false
  let isClosed = false
  for (let i = start + 1; i < text.length && !isClosed; i++) {
    const c = text[i]
    if (inString) {
      if (c === '\\') i++
      else if (c === '"') inString = false
    } else if (c === '"') inString = true
    else if (c === '{') {
      if (depth === 0) from = i
      depth++
    } else if (c === '}') {
      depth--
      if (depth === 0) {
        try {
          objects.push(JSON.parse(text.slice(from, i + 1)))
        } catch {
          // a malformed one is skipped; the rest still count
        }
      }
    } else if (c === ']' && depth === 0) isClosed = true
  }
  const verdicts = objects.flatMap((r): Graded[] => {
    const o = r as Record<string, unknown>
    const verdict = verdictOf(o.verdict)
    if (typeof o.name !== 'string' || !verdict) return []
    const reason = String(o.reason ?? '')
    const missed = typeof o.missed === 'string' ? o.missed.trim() : ''
    const sure = typeof o.confidence === 'string' && CONFIDENCES.includes(o.confidence.trim().toLowerCase()) ? { confidence: o.confidence.trim().toLowerCase() as Confidence } : {}
    // shallow only with a bug the grader can name; told whoever fixes it, as the case to add
    if (verdict === 'shallow' && missed === '') return [{ name: o.name, summary: String(o.summary ?? ''), verdict: 'strong', reason: `${reason} (Graded strong: no bug it would miss was named.)`.trim(), ...sure }]
    if (verdict === 'strong') {
      // strong only with a bug the grader can name; with none, another reviewer could fairly disagree
      const catches = catchesOf(o.catches)
      if (catches === null) return [{ name: o.name, summary: String(o.summary ?? ''), verdict, reason: `${reason} (It named no bug the test would catch.)`.trim(), confidence: 'low' }]
      return [{ name: o.name, summary: String(o.summary ?? ''), verdict, reason: `${reason} It catches: ${catches.bug}`.trim(), ...sure, catches }]
    }
    return [{ name: o.name, summary: String(o.summary ?? ''), verdict, reason: verdict === 'shallow' ? `${reason} It would miss: ${missed}` : reason, ...sure }]
  })
  return { verdicts, isCut: !isClosed }
}

export type Graded = { name: string; summary: string; verdict: Verdict; reason: string; confidence?: Confidence; catches?: Catches }

// The bug a strong test would catch, as its grader named it: in a sentence, and, where the grader
// saw the code under test, the change to it that makes the bug, for a background run to measure
export type Catches = { bug: string; file?: string; find?: string; replace?: string }
export const catchesOf = (given: unknown): Catches | null => {
  if (typeof given === 'string') return given.trim() === '' ? null : { bug: given.trim() }
  if (given === null || typeof given !== 'object') return null
  const o = given as Record<string, unknown>
  const text = (v: unknown): string => (typeof v === 'string' ? v : '')
  const bug = text(o.bug).trim()
  if (bug === '') return null
  const [file, find, replace] = [text(o.file).trim(), text(o.find), text(o.replace)]
  // a change only where it names a file and alters something
  return file !== '' && find !== '' && find !== replace ? { bug, file, find, replace } : { bug }
}

// A test the grader graded case by case (Test › xdr role, Test/xdr role, Test > xdr role) when
// asked for the test: one verdict for it, the worst of its cases', its reason saying which case
// earned it. A verdict under the test's own name stands, its cases' set aside
const CASE_MARK = /^\s*(?:›|>|\/|::|-)\s*/
const WORST: Verdict[] = ['hollow', 'duplicate', 'shallow', 'brittle', 'strong']
export const foldCases = <V extends { name: string; verdict: Verdict; reason: string; summary: string }>(names: string[], verdicts: V[]): V[] => {
  const caseOf = (v: V): { test: string; label: string } | null => {
    if (among(names, v.name)) return null
    // the longest asked name it extends, so Test_A is not taken for Test_AB's case
    const test = names.filter(n => !isTemplate(n) && v.name.startsWith(n) && CASE_MARK.test(v.name.slice(n.length))).sort((a, b) => b.length - a.length)[0]
    return test === undefined ? null : { test, label: v.name.slice(test.length).replace(CASE_MARK, '') }
  }
  const cases = new Map<string, { label: string; v: V }[]>()
  const rest: V[] = []
  for (const v of verdicts) {
    const c = caseOf(v)
    if (c === null) rest.push(v)
    else cases.set(c.test, [...(cases.get(c.test) ?? []), { label: c.label, v }])
  }
  const folded = [...cases.entries()]
    .filter(([test]) => !rest.some(v => v.name === test))
    .map(([test, of]): V => {
      const worst = [...of].sort((a, b) => WORST.indexOf(a.v.verdict) - WORST.indexOf(b.v.verdict))[0]!
      const labels = of.map(c => JSON.stringify(c.label)).join(', ')
      const reason = worst.v.verdict === 'strong' ? `Graded case by case (${labels}), each strong. ${worst.v.reason}` : `Graded case by case (${labels}); the case ${JSON.stringify(worst.label)} is ${worst.v.verdict}: ${worst.v.reason}`
      return { ...worst.v, name: test, reason: reason.trim() }
    })
  return [...rest, ...folded]
}

// a name as a model may echo it back: curly quotes straight, dashes plain, an escape's
// backslash dropped, each run of space one
const loose = (name: string): string =>
  name
    .replace(/[‘’‚‛′]/g, "'")
    .replace(/[“”„‟″]/g, '"')
    .replace(/[‐‑‒–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/\\(['"`\\])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim()

// each verdict under the name it was asked by: a verdict whose name differs from one asked
// name alone only in its quotes, dashes, escapes or spacing answers for that test
// and one named with the groups around it ("ApiClient › appends every file") answers for the
// test asked by the end of that name, where one test alone has it; a name that extends an
// asked one by a case mark is a case of that test, not a group's
const GROUP_MARK = /\s+(?:›|>)\s+/
export const asAsked = <V extends { name: string }>(names: string[], verdicts: V[]): V[] => {
  const asked = [...new Set(names)]
  const alikeTo = (name: string): string[] => asked.filter(n => !isTemplate(n) && loose(n) === loose(name))
  return verdicts.map(v => {
    if (among(names, v.name)) return v
    const alike = alikeTo(v.name)
    if (alike.length === 1) return { ...v, name: alike[0]! }
    if (asked.some(n => !isTemplate(n) && v.name.startsWith(n) && CASE_MARK.test(v.name.slice(n.length)))) return v
    const parts = v.name.split(GROUP_MARK)
    for (let k = 1; k < parts.length; k++) {
      const tail = parts.slice(k).join(' › ')
      const fitting = asked.filter(n => isTemplate(n) && fits(n, tail))
      const matched = [...new Set([...alikeTo(tail), ...(among(asked.filter(n => !isTemplate(n)), tail) ? [tail] : [])])]
      if (matched.length + fitting.length === 1) return { ...v, name: matched[0] ?? tail }
      if (matched.length + fitting.length > 1) return v
    }
    // the group's name joined by a space or a colon alone ("parseDebugId reads the debug ID"):
    // the longest test asked the name ends with, where a space or a colon comes before it (one
    // ending part way into a word is no group's: no shorter test is taken in its stead)
    const said = loose(v.name)
    const ending = asked.filter(n => !isTemplate(n) && said.length > loose(n).length && said.endsWith(loose(n))).sort((a, b) => b.length - a.length)[0]
    return ending !== undefined && /[\s:]$/.test(said.slice(0, said.length - loose(ending).length)) ? { ...v, name: ending } : v
  })
}

// the grader's reply limit, in tokens: a reply cut off there loses the verdicts it had not reached
export const MAX_REPLY = 8000

// Why a test asked about got no verdict from this reply, for its row to say; null when it got
// one. The likely causes in turn: the reply cut off before it, no verdict read at all, its own
// verdict unreadable (an unknown grade, a broken object), a verdict under another name, left out
export const unratedWhy = (text: string, verdicts: Graded[], isCut: boolean, names: string[], name: string, model: string): string | null => {
  if (verdicts.some(v => fits(name, v.name))) return null
  // the tests answered, not the verdicts: a loop's or table's cases are many verdicts for one test
  const answered = names.filter(n => verdicts.some(v => fits(n, v.name))).length
  const count = `it gave ${answered} of the ${names.length} verdicts asked for`
  if (isCut) return `The grader's (${model}) reply was cut off at its ${MAX_REPLY}-token limit before it reached this test: ${count}.`
  if (verdicts.length === 0) {
    const said = text.replace(/\s+/g, ' ').trim()
    return `The grader (${model}) answered with no verdict it could read: "${said.length > 160 ? `${said.slice(0, 160)}…` : said}".`
  }
  // the test's own object, as it came back: its name as JSON writes it, and the braces around it
  const at = isTemplate(name) ? -1 : text.indexOf(JSON.stringify(name))
  if (at >= 0) {
    const from = text.lastIndexOf('{', at)
    const to = text.indexOf('}', at)
    const own = text.slice(from < 0 ? at : from, to < 0 ? undefined : to + 1).replace(/\s+/g, ' ')
    return `The grader (${model}) answered for this test, but its verdict could not be read: ${own.length > 240 ? `${own.slice(0, 240)}…` : own}`
  }
  const strays = verdicts.filter(v => !among(names, v.name)).map(v => JSON.stringify(v.name))
  if (strays.length > 0) return `The grader (${model}) gave no verdict under this test's name; it answered for ${strays.slice(0, 3).join(', ')}${strays.length > 3 ? ` and ${strays.length - 3} more` : ''}, which no test asked about is named.`
  return `The grader (${model}) left this test out of its answer: ${count}.`
}

files.hooks/measure.ts:
// Strong grades measured: each names a bug its test would catch, and where the grader saw the
// code under test, the change that makes it. A few at a time, while the session is idle, the
// change is made and the test run: one that still passes let its bug through. Pure: no engine
// calls

// a strong grade's change to measure, by file::name; textOf: the test's own text when graded
export type Proposed = { bug: string; file: string; find: string; replace: string; textOf: string }
// held: the test failed with the change; through: it passed; unmeasured: the run showed nothing
// (the test failed unchanged, or the change did not build), why saying which
export type Measured = { state: 'held' | 'through' | 'unmeasured'; change: string; textOf: string; why?: string }

// how many proposals are kept: the most recent, by when they were graded
export const MAX_PROPOSED = 3000

// The next tests to measure: strong now, with a change proposed for their text as it stands, and
// not measured at that text; a shuffled pick, so a big project's sample is spread over it
export const pickToMeasure = (
  strong: { key: string; textOf: string | undefined }[],
  proposed: Record<string, Proposed>,
  measured: Record<string, Measured>,
  count: number,
  random: () => number = Math.random,
): string[] => {
  const open = strong.filter(t => {
    const p = proposed[t.key]
    if (!p || (t.textOf !== undefined && p.textOf !== t.textOf)) return false
    return measured[t.key]?.textOf !== p.textOf
  })
  for (let i = open.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[open[i], open[j]] = [open[j]!, open[i]!]
  }
  return open.slice(0, Math.max(0, count)).map(t => t.key)
}

// the code with the change made, or why it cannot be: the text to find must be there exactly once
export const mutate = (code: string, find: string, replace: string): { code: string } | { why: string } => {
  const count = code.split(find).length - 1
  if (count !== 1) return { why: count === 0 ? 'the text to change is not in the file' : `the text to change is in the file ${count} times, not once` }
  return { code: code.replace(find, () => replace) }
}

// how a change is named, in notes and reasons
export const changeOf = (find: string, replace: string, file: string): string => `${JSON.stringify(find)} replaced by ${JSON.stringify(replace)} in ${file}`

// a Go build's overlay: the file built from another, the source left as it is
export const overlayOf = (file: string, replacement: string): string => JSON.stringify({ Replace: { [file]: replacement } })

// the grade a test that let its named bug through is given instead of strong
export const throughGrade = (bug: string, change: string): { verdict: 'shallow'; reason: string } => ({
  verdict: 'shallow',
  reason: `Measured: it still passes with ${change}, the bug its strong grade named. It would miss: ${bug}`,
})

// the pane's line: of the strong tests listed, how many a measured change made fail, and how
// many tests let theirs through (graded shallow since); null before any is measured
export const measuredLine = (strongKeys: string[], measured: Record<string, Measured>): string | null => {
  const results = Object.values(measured)
  const through = results.filter(m => m.state === 'through').length
  if (results.length === 0) return null
  const held = strongKeys.filter(k => measured[k]?.state === 'held').length
  return `measured: ${held} of ${strongKeys.length} strong${through > 0 ? ` · ${through} let their named bug through (now shallow)` : ''}`
}

files.hooks/gocover.ts:
// Go's coverage profile (go test -coverprofile) read: pure, so the engine calls stay in register.tsx
//
// Each line after the mode is one block: `<import path>/<file>.go:<from>,<to> <statements> <count>`.
// A block can appear more than once (a package tested by several test binaries): it counts once,
// covered when any run covered it. Go measures statements alone: no lines, branches or functions

// the module path go.mod declares, which every import path in the profile starts with
export const moduleOf = (goMod: string): string | null => goMod.match(/^module\s+(\S+)/m)?.[1]?.replace(/^"|"$/g, '') ?? null

type Tally = { total: number; covered: number }

// isKept: whether a file counts (not one the project's ignore list names)
export const goProfileOf = (profile: string, module: string | null, cwd: string, isKept: (file: string) => boolean = () => true): { statements: number | null; byFile: ({ file: string } & Tally)[]; byPackage: ({ name: string } & Tally)[] } => {
  const blocks = new Map<string, { file: string; statements: number; isCovered: boolean }>()
  for (const line of profile.split('\n')) {
    const m = line.trim().match(/^(.+\.go):(\d+\.\d+,\d+\.\d+) (\d+) (\d+)$/)
    if (!m) continue
    const [, path, span, statements, count] = m
    const key = `${path}:${span}`
    const was = blocks.get(key)
    blocks.set(key, { file: path!, statements: Number(statements), isCovered: (was?.isCovered ?? false) || Number(count) > 0 })
  }
  // an import path inside the module is a file in the project; one outside it keeps its path
  const local = (path: string): string => (module && path.startsWith(`${module}/`) ? `${cwd}/${path.slice(module.length + 1)}` : path)
  const files = new Map<string, Tally>()
  for (const b of blocks.values()) {
    const f = files.get(b.file) ?? { total: 0, covered: 0 }
    f.total += b.statements
    if (b.isCovered) f.covered += b.statements
    files.set(b.file, f)
  }
  const byFile = [...files].map(([path, f]) => ({ file: local(path), ...f })).filter(f => isKept(f.file))
  const total = byFile.reduce((s, f) => s + f.total, 0)
  const covered = byFile.reduce((s, f) => s + f.covered, 0)
  // a package is its files' folder: by its path in the project ('./' the module's root), one
  // outside the module by its import path
  const packages = new Map<string, Tally>()
  for (const f of byFile) {
    const dir = f.file.slice(0, f.file.lastIndexOf('/'))
    const name = dir === cwd ? './' : `${dir.startsWith(`${cwd}/`) ? dir.slice(cwd.length + 1) : dir}/`
    const p = packages.get(name) ?? { total: 0, covered: 0 }
    p.total += f.total
    p.covered += f.covered
    packages.set(name, p)
  }
  const byPackage = [...packages].filter(([, p]) => p.total > 0).map(([name, p]) => ({ name, ...p }))
  return { statements: total > 0 ? (covered / total) * 100 : null, byFile, byPackage }
}

// A folder's run (go test ./<folder>/...) merged into the module's last profile: the blocks of
// the folder's files, and of every folder under it, are the new run's; the rest are kept
export const mergeProfile = (whole: string, part: string, module: string | null, rel: string): string => {
  const isInFolder = (line: string): boolean => module !== null && (line.match(/^(.+\.go):/)?.[1] ?? '').startsWith(`${module}/${rel}/`)
  const blocks = (profile: string): string[] => profile.split('\n').filter(l => l.trim() !== '' && !l.startsWith('mode:'))
  const mode = part.match(/^mode: .+$/m)?.[0] ?? whole.match(/^mode: .+$/m)?.[0] ?? 'mode: set'
  return [mode, ...blocks(whole).filter(l => !isInFolder(l)), ...blocks(part), ''].join('\n')
}

// what a package is for, read from one of its files: a command (package main), or a test helper
// (mocks, or code that imports testing or a mocking library), which coverage tells apart from the
// code tests are written for; undefined for anything else
export type PackageRole = 'command' | 'helper'
const HELPER_IMPORT = /^\s*(?:import\s+)?(?:[\w.]+\s+)?"(?:testing|github\.com\/stretchr\/testify\/mock|go\.uber\.org\/mock\/gomock|github\.com\/golang\/mock\/gomock)"/m
export const roleOf = (source: string): PackageRole | undefined => {
  const name = source.match(/^package\s+(\w+)/m)?.[1]
  if (name === undefined) return undefined
  if (name === 'main') return 'command'
  return isHelperName(name) || HELPER_IMPORT.test(source) ? 'helper' : undefined
}

// a folder or package named as test code: mocks, fakes, testutil, fixtures, or Go's xxxtest
// convention (httptest, receipttest), not an English word that happens to end in test
const NOT_HELPERS = new Set(['latest', 'contest', 'protest', 'attest', 'detest', 'greatest', 'smallest', 'fastest', 'shortest', 'longest', 'biggest', 'smartest'])
export const isHelperName = (name: string): boolean =>
  /^(?:\w*mocks?|fakes?|testutils?|testhelpers?|testing|fixtures|testdata|testkit|testsupport)$/.test(name) || (/^\w+test$/.test(name) && !NOT_HELPERS.has(name))

// Go's standard header for generated code, "Code generated … DO NOT EDIT.", before the package
// clause: code no one writes tests for
export const isGenerated = (source: string): boolean => {
  const at = source.search(/^package\s/m)
  const head = at === -1 ? source : source.slice(0, at)
  return /^\/\/ Code generated .* DO NOT EDIT\.$/m.test(head)
}

