export type Verdict = 'strong' | 'shallow' | 'brittle' | 'hollow' | 'duplicate'
/** how sure the grader was: medium or low when another reviewer could fairly grade it otherwise; none from before it was asked */
export type Confidence = 'high' | 'medium' | 'low'

export type TrackedTest = {
  id: string
  file: string
  name: string
  at: number
  status: 'pending' | 'done' | 'failed'
  summary?: string
  verdict?: Verdict
  reason?: string
  confidence?: Confidence
  /** a Go suite test's suite */
  suite?: string
  /** what the session sent to have it regraded, when its verdict was given on evidence */
  evidence?: string
  /** the test's own text, fingerprinted, when the evidence was accepted: the verdict holds while it is unchanged */
  evidenceOf?: string
  /** its grade before an edit had it graded again, for the fixer to see whether that concern was met */
  before?: Before
}
/** a grade a test had before it was graded again */
export type Before = { verdict: Verdict; reason?: string }

export type Coverage = {
  lines: number | null
  statements: number | null
  branches: number | null
  functions: number | null
  source: string
  updatedAt: number | null
  /** line coverage by folder, its path in the project ('' the project), each with all beneath it */
  byDir?: Record<string, { total: number; covered: number }>
  /** Go's statements by package, by its path in the project ('./' the module's root); role: a
   * command (package main) or a test helper (mocks, code that imports testing), told by its source */
  byPackage?: { name: string; total: number; covered: number; role?: 'command' | 'helper' }[]
  /** a project of parts each measured on its own (backend/ in Go, mobile/ with jest): each part's figures, by its folder */
  parts?: CoveragePart[]
  /** the statements the report counted and those covered, which add up across parts where lines and percentages do not */
  statementCount?: { total: number; covered: number }
}
export type CoveragePart = { dir: string; lines: number | null; statements: number | null; branches: number | null; functions: number | null; source: string }

/** a test already in the project, as Grade all tests judged it (no verdict: the grader gave none; isUngraded: listed, never graded) */
// textOf: the test's own text, fingerprinted, when it was graded: a changed file's test whose own text is the same keeps its grade
// before: its grade before it was last graded again
export type ExistingTest = { file: string; name: string; verdict?: Verdict; summary?: string; reason?: string; confidence?: Confidence; isPending?: boolean; isUngraded?: boolean; suite?: string; evidence?: string; evidenceOf?: string; textOf?: string; before?: Before }

/** Grade all tests: how far a run has got, and what the last one found */
// hashes: each graded file's contents, as fingerprinted when its results were made
// graded, remembered: how many tests the last run sent to the grader, and how many it took from before
export type ExistingRun = {
  state: 'idle' | 'running' | 'failed'
  done: number
  total: number
  message?: string
  results: ExistingTest[]
  finishedAt?: number
  hashes?: Record<string, string>
  graded?: number
  remembered?: number
  /** while running: a Regrade all, every file graded again */
  isFresh?: boolean
  /** while running: a run of these files alone (their paths in the project), the rest left be */
  only?: string[]
  /** while running: what a narrowed run grades, as Claude's note names it (a folder, the branch's changes) */
  scope?: string
  /** the files the last run graded again for a change since their last grading, and graded for the first time, by their paths in the project */
  changed?: string[]
  added?: string[]
  /** in the session's state: how many of the results' chunks hold the results, their own field left empty */
  chunks?: number
  /** what the last run's grader calls cost, in tokens: in (of them from the prompt cache) and out */
  spent?: { input: number; cached: number; output: number; cost?: number; unpriced?: number }
}

/** a test's grade as Claude is told it */
export type GradeReport = { file: string; name: string; verdict?: Verdict; reason?: string; before?: Before }

export type CoverageRun = { state: 'idle' | 'running' | 'failed'; message?: string }

declare module 'claude-code' {
  interface PluginState {
    'test-grader': {
      tests: TrackedTest[]
      coverage: Coverage | null
      run: CoverageRun
      existing: ExistingRun
      /** the results of `existing`, in order, a chunk each: one value is held to 4 MiB, and a project of thousands of tests is more */
      results: StateFamily<ExistingTest[]>
      /** why the last note to Claude was not added, until one is */
      noteError: string | null
      /** the rows pressed open in the pane, by their key */
      open: string[]
      /** a file pressed open (true) or closed (false) this session; absent, its default */
      fileOpen: Record<string, boolean>
      /** why the last Open in editor opened nothing, until one does */
      openError: string | null
      /** each listed test file's contents as last seen, fingerprinted: a change since is caught at a turn's end */
      seen: Record<string, string>
      /** the session the open and closed files are kept for: a new one starts them closed */
      openFor: string | null
      /** the folder the session started in, which the pane lists and grades, for that session */
      root: { session: string | null; dir: string } | null
      /** the project's coverage run as a note names it (npx jest --coverage); null: none test-grader knows */
      coverWith: string | null
      /** how many weak or useless grades in a row each test Claude wrote or edited has had, by file::name; a good one leaves */
      rounds: Record<string, number>
      /** the tests there before, edited this session, by file:name: marked modified */
      modified: string[]
      /** each test run from the pane, by file:name: running, or how it ended and what it printed last */
      testRuns: Record<string, { state: 'running' | 'passed' | 'failed'; command?: string; tail?: string }>
      /** how many times the project folders of the listed test files were looked up: a lookup done draws the pane again */
      basesFound: number
      /** how many times the files' layers were read: a reading done draws the pane again */
      layersFound: number
      /** the tests the last coverage run ran, by a JS file's path or a Go package's folder, each with how it ended; measured: the folders it reached */
      ranRecord: { at: number; measured: string[]; by: Record<string, Record<string, 'passed' | 'failed' | 'skipped'>>; tagsBy?: Record<string, string[]> } | null
      /** the mutations test_verify measured a test let through, by file::name: the change, and the test's own text then */
      survived: Record<string, { change: string; textOf: string }[]>
      /** the change to the code each strong grade named as the bug its test would catch, by file::name; textOf: the test's own text then */
      proposed: Record<string, { bug: string; file: string; find: string; replace: string; textOf: string }>
      /** what the background run measured of those changes, by file::name: held (the test failed), through (it passed: graded shallow) or unmeasured, why */
      measuredStrong: Record<string, { state: 'held' | 'through' | 'unmeasured'; change: string; textOf: string; why?: string }>
      /** why each test its last grader call gave no verdict got none, by file::name; a verdict clears it */
      unrated: Record<string, string>
      /** why the last grader call gave no answer, with its model, until one answers */
      graderError: string | null
      /** why the grades could not be saved to outlive the session, until a save goes through */
      saveError: string | null
      /** grades waiting to go to Claude as one note, once no grading is under way */
      outbox: { accepted: GradeReport[]; going: GradeReport[]; spent: GradeReport[] }
    }
  }
}
